-- Ordinary full-gross allocation. V1-V9 and SOURCE_REVIEW usage identities are immutable.
CREATE TABLE plugin_finance_cash_allocation_guard (
 tenant_id uuid NOT NULL,book_id uuid NOT NULL,year_id uuid NOT NULL,allocation_version bigint NOT NULL DEFAULT 0 CHECK(allocation_version>=0),PRIMARY KEY(tenant_id,book_id,year_id),FOREIGN KEY(tenant_id,book_id,year_id) REFERENCES plugin_finance_year_guard(tenant_id,book_id,year_id));
ALTER TABLE plugin_finance_cash_policy_revision ADD UNIQUE(tenant_id,book_id,year_id,id,content_digest);
CREATE TABLE plugin_finance_cash_allocation (
 tenant_id uuid NOT NULL,book_id uuid NOT NULL,year_id uuid NOT NULL,id uuid NOT NULL,legal_entity_id uuid NOT NULL,review_id uuid NOT NULL,review_usage_id uuid NOT NULL,review_content_digest text NOT NULL,review_version_at_prepare bigint NOT NULL,claim_id uuid NOT NULL,raw_registration_id uuid NOT NULL,claim_generation bigint NOT NULL,claim_content_digest text NOT NULL,source_match_generation bigint NOT NULL,
 content_version bigint NOT NULL DEFAULT 1 CHECK(content_version=1),content_digest text NOT NULL CHECK(content_digest~'^[a-f0-9]{64}$'),content jsonb NOT NULL,total numeric(28,8) NOT NULL CHECK(total>0 AND total=trunc(total,2)),prepared_by uuid NOT NULL,prepared_username text NOT NULL,last_edited_by uuid NOT NULL CHECK(last_edited_by=prepared_by),created_at timestamptz NOT NULL DEFAULT now(),
 supersedes_allocation_id uuid,expected_superseded_version bigint,superseded_content_digest text,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','SUBMITTED','APPROVED','REJECTED','CANCELLED','RELEASED','SUPERSEDED')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),submitted_at timestamptz,submission_expires_at timestamptz,approved_by uuid,approved_at timestamptz,approved_dependency_id uuid,activation_replacement_id uuid,decision_by uuid,decision_at timestamptz,decision_reason text,release_request_id uuid,supersession_request_id uuid,superseded_by_allocation_id uuid,released_by uuid,released_at timestamptz,
 PRIMARY KEY(tenant_id,book_id,year_id,id),UNIQUE(tenant_id,book_id,year_id,id,review_id,review_usage_id,claim_id,raw_registration_id,claim_generation,claim_content_digest,review_content_digest,content_digest,approved_dependency_id),
 FOREIGN KEY(tenant_id,book_id,legal_entity_id) REFERENCES plugin_finance_book(tenant_id,id,legal_entity_id),FOREIGN KEY(tenant_id,book_id,year_id) REFERENCES plugin_finance_cash_allocation_guard(tenant_id,book_id,year_id),
 FOREIGN KEY(tenant_id,book_id,year_id,review_id,claim_id,raw_registration_id,claim_generation,claim_content_digest,review_content_digest,review_usage_id) REFERENCES plugin_finance_cash_source_review(tenant_id,book_id,year_id,id,claim_id,raw_registration_id,claim_generation,claim_content_digest,content_digest,approved_usage_id),
 FOREIGN KEY(tenant_id,book_id,year_id,review_usage_id,review_id,claim_id,raw_registration_id,claim_generation,claim_content_digest,review_content_digest) REFERENCES plugin_finance_cash_claim_usage(tenant_id,book_id,year_id,id,source_review_id,claim_id,raw_registration_id,claim_generation,claim_content_digest,consumer_content_digest),
 FOREIGN KEY(tenant_id,book_id,year_id,supersedes_allocation_id) REFERENCES plugin_finance_cash_allocation(tenant_id,book_id,year_id,id),CHECK((supersedes_allocation_id IS NULL AND expected_superseded_version IS NULL AND superseded_content_digest IS NULL) OR (supersedes_allocation_id IS NOT NULL AND expected_superseded_version>0 AND superseded_content_digest~'^[a-f0-9]{64}$')));
