 PRIMARY KEY(tenant_id,book_id,year_id,id),UNIQUE(tenant_id,book_id,year_id,id,old_allocation_id,old_content_digest,old_dependency_id),UNIQUE(tenant_id,book_id,year_id,id,old_allocation_id,old_content_digest,old_dependency_id,new_allocation_id),UNIQUE(tenant_id,book_id,year_id,id,new_allocation_id,new_content_digest,new_dependency_id),
