 tenant_id uuid NOT NULL,book_id uuid NOT NULL,year_id uuid NOT NULL,allocation_id uuid NOT NULL,dependency_id uuid NOT NULL,content_digest text NOT NULL,review_id uuid NOT NULL,review_usage_id uuid NOT NULL,claim_id uuid NOT NULL,raw_registration_id uuid NOT NULL,claim_generation bigint NOT NULL,claim_content_digest text NOT NULL,review_content_digest text NOT NULL,approved_by uuid NOT NULL,approved_at timestamptz NOT NULL,replacement_id uuid,
 PRIMARY KEY(tenant_id,book_id,year_id,allocation_id),FOREIGN KEY(tenant_id,book_id,year_id,dependency_id,allocation_id,content_digest,review_id,review_usage_id,claim_id,raw_registration_id,claim_generation,claim_content_digest,review_content_digest) REFERENCES plugin_finance_cash_allocation_dependency(tenant_id,book_id,year_id,id,allocation_id,consumer_content_digest,review_id,review_usage_id,claim_id,raw_registration_id,claim_generation,claim_content_digest,review_content_digest) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(tenant_id,book_id,year_id,replacement_id,allocation_id,content_digest,dependency_id) REFERENCES plugin_finance_cash_allocation_replacement(tenant_id,book_id,year_id,id,new_allocation_id,new_content_digest,new_dependency_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TRIGGER finance_cash_allocation_activation_immutable BEFORE UPDATE OR DELETE ON plugin_finance_cash_allocation_activation FOR EACH ROW EXECUTE FUNCTION plugin_finance_immutable();
CREATE TABLE plugin_finance_cash_allocation_outbox (
 tenant_id uuid NOT NULL,book_id uuid NOT NULL,year_id uuid NOT NULL,id uuid NOT NULL,allocation_id uuid NOT NULL,request_id uuid,source_kind text NOT NULL CHECK(source_kind IN('ALLOCATION','RELEASE','REPLACEMENT')),source_version bigint NOT NULL,allocation_version bigint NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,book_id,year_id,id),UNIQUE NULLS NOT DISTINCT(tenant_id,book_id,year_id,allocation_id,request_id,source_kind,source_version,event_type),FOREIGN KEY(tenant_id,book_id,year_id,allocation_id) REFERENCES plugin_finance_cash_allocation(tenant_id,book_id,year_id,id));
CREATE TRIGGER finance_cash_allocation_outbox_immutable BEFORE UPDATE OR DELETE ON plugin_finance_cash_allocation_outbox FOR EACH ROW EXECUTE FUNCTION plugin_finance_immutable();
CREATE FUNCTION plugin_finance_cash_allocation_parent(t uuid,b uuid,y uuid,rid uuid) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE r record;u record;s jsonb;BEGIN
 SELECT * INTO STRICT r FROM plugin_finance_cash_source_review WHERE tenant_id=t AND book_id=b AND year_id=y AND id=rid;
 SELECT * INTO u FROM plugin_finance_cash_claim_usage WHERE tenant_id=t AND book_id=b AND year_id=y AND id=r.approved_usage_id AND source_review_id=rid;
 IF r.status<>'APPROVED' OR NOT FOUND OR u.state<>'ACTIVE' OR u.usage_kind<>'SOURCE_REVIEW' THEN RAISE EXCEPTION 'CASH_ALLOCATION_PARENT_STALE';END IF;
 IF EXISTS(SELECT 1 FROM plugin_finance_cash_source_review_release WHERE tenant_id=t AND book_id=b AND year_id=y AND review_id=rid AND status='REQUESTED') THEN RAISE EXCEPTION 'CASH_ALLOCATION_PARENT_RELEASE_PENDING';END IF;
 PERFORM plugin_finance_cash_review_evidence_check(t,b,y,rid);
 s:=plugin_finance_cash_review_snapshot(t,b,y,r.raw_registration_id,r.claim_id);
 IF s IS DISTINCT FROM r.content->'claimSnapshot' THEN RAISE EXCEPTION 'CASH_ALLOCATION_PARENT_FACTS_STALE';END IF;
 RETURN jsonb_build_object('reviewId',r.id,'expectedReviewVersion',r.version,'reviewContentDigest',r.content_digest,'activeReviewUsageId',u.id,'claimId',r.claim_id,'claimGeneration',r.claim_generation,'claimContentDigest',r.claim_content_digest,'sourceMatchGeneration',r.source_match_generation,'rawRegistrationId',r.raw_registration_id,'rawContentDigest',s->>'rawContentDigest','claimKind',r.claim_kind,'correctionId',s->'correctionId','journalId',s->'journalId','lineNo',s->'lineNo','journalVersion',s->'journalVersion','postingSeq',s->'postingSeq','postingDigest',s->'postingDigest','accountId',s->'accountId','scopeRevisionId',s->'cashScopeRevisionId','scopeVersion',s->'cashScopeVersion','scopeDigest',s->'cashScopeDigest','occurredDate',s->'occurredDate','direction',s->'direction','currency',s->'currency','grossAmount',s->'normalizedAmount','transactionKind',s->'sourceIdentity'->'transactionKind');
END $$;
CREATE FUNCTION plugin_finance_cash_allocation_policy_snapshot(t uuid,b uuid,y uuid,pid uuid) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE p record;BEGIN
 SELECT * INTO STRICT p FROM plugin_finance_cash_policy_revision WHERE tenant_id=t AND book_id=b AND year_id=y AND id=pid;
 RETURN jsonb_build_object('policyId',p.id,'policyCode',p.policy_code,'revision',p.revision,'policyVersion',p.version,'contentDigest',p.content_digest,'dictionaryVersion',p.dictionary_version,'standard',p.standard,'templateId',p.template_id,'transactionKind',p.transaction_kind,'businessPurpose',p.business_purpose,'direction',p.direction,'semanticLeaf',p.semantic_leaf,'rowId',p.row_id,'reportScope',p.report_scope,'currency',p.currency,'transactionForm',p.transaction_form,'effectiveFrom',p.effective_from,'effectiveTo',p.effective_to,'approvedBy',p.approved_by,'approvedAt',to_char(p.approved_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END $$;
CREATE FUNCTION plugin_finance_cash_allocation_fresh_lines(t uuid,b uuid,y uuid,aid uuid) RETURNS void LANGUAGE plpgsql AS $$ DECLARE a record;l record;p record;o record;n integer;sum_amount numeric;BEGIN
 SELECT * INTO STRICT a FROM plugin_finance_cash_allocation WHERE tenant_id=t AND book_id=b AND year_id=y AND id=aid;
 SELECT count(*),sum(amount) INTO n,sum_amount FROM plugin_finance_cash_allocation_line WHERE tenant_id=t AND book_id=b AND year_id=y AND allocation_id=aid;
 IF n<1 OR n>20 OR n<>jsonb_array_length(a.content->'lines') OR sum_amount IS DISTINCT FROM a.total OR sum_amount IS DISTINCT FROM (a.content->'parentSnapshot'->>'grossAmount')::numeric THEN RAISE EXCEPTION 'CASH_ALLOCATION_SUM_MISMATCH';END IF;
 FOR l IN SELECT * FROM plugin_finance_cash_allocation_line WHERE tenant_id=t AND book_id=b AND year_id=y AND allocation_id=aid LOOP
  SELECT * INTO STRICT p FROM plugin_finance_cash_policy_revision WHERE tenant_id=t AND book_id=b AND year_id=y AND id=l.policy_id;
  IF p.status<>'APPROVED' OR p.version<>l.policy_version OR p.content_digest<>l.policy_content_digest OR p.legal_entity_id<>a.legal_entity_id OR p.transaction_kind IS DISTINCT FROM a.content->'parentSnapshot'->>'transactionKind' OR p.business_purpose<>l.business_purpose OR p.direction IS DISTINCT FROM a.content->'parentSnapshot'->>'direction' OR (a.content->'parentSnapshot'->>'occurredDate')::date NOT BETWEEN p.effective_from AND p.effective_to OR EXISTS(SELECT 1 FROM plugin_finance_cash_policy_retirement WHERE tenant_id=t AND book_id=b AND year_id=y AND policy_id=p.id AND status='REQUESTED') OR l.policy_snapshot IS DISTINCT FROM plugin_finance_cash_allocation_policy_snapshot(t,b,y,p.id) THEN RAISE EXCEPTION 'CASH_ALLOCATION_POLICY_UNAVAILABLE';END IF;
  PERFORM plugin_finance_cash_policy_check_evidence(t,b,y,p.id);
  SELECT * INTO STRICT o FROM plugin_finance_original WHERE tenant_id=t AND book_id=b AND year_id=y AND id=l.evidence_original_id;
  IF (l.evidence_version,l.evidence_sha256,l.evidence_filename) IS DISTINCT FROM (o.version,o.sha256,o.filename) OR encode(sha256(o.content),'hex')<>l.evidence_sha256 OR octet_length(o.content)<>o.size_bytes THEN RAISE EXCEPTION 'CASH_ALLOCATION_EVIDENCE_STALE';END IF;
 END LOOP;
END $$;
CREATE FUNCTION plugin_finance_cash_allocation_guard_fn() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE raw record;p jsonb;old_alloc record;decision record;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CASH_ALLOCATION_HISTORY_IMMUTABLE';END IF;
 SELECT * INTO STRICT raw FROM plugin_finance_cash_movement_registration WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.raw_registration_id FOR UPDATE;
 PERFORM plugin_finance_cash_match_open(NEW.tenant_id,NEW.book_id,NEW.year_id,raw.occurred_date);
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.version<>1 OR NEW.submitted_at IS NOT NULL OR NEW.submission_expires_at IS NOT NULL OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL OR NEW.approved_dependency_id IS NOT NULL OR NEW.activation_replacement_id IS NOT NULL OR NEW.decision_by IS NOT NULL OR NEW.decision_at IS NOT NULL OR NEW.decision_reason IS NOT NULL OR NEW.release_request_id IS NOT NULL OR NEW.supersession_request_id IS NOT NULL OR NEW.superseded_by_allocation_id IS NOT NULL OR NEW.released_by IS NOT NULL OR NEW.released_at IS NOT NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_INITIAL_DRAFT_REQUIRED';END IF;
  p:=plugin_finance_cash_allocation_parent(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.review_id);
  IF NEW.content->'parentSnapshot' IS DISTINCT FROM p OR (NEW.review_usage_id,NEW.review_content_digest,NEW.review_version_at_prepare,NEW.claim_id,NEW.claim_generation,NEW.claim_content_digest,NEW.source_match_generation,NEW.legal_entity_id,NEW.total) IS DISTINCT FROM ((p->>'activeReviewUsageId')::uuid,p->>'reviewContentDigest',(p->>'expectedReviewVersion')::bigint,(p->>'claimId')::uuid,(p->>'claimGeneration')::bigint,p->>'claimContentDigest',(p->>'sourceMatchGeneration')::bigint,raw.legal_entity_id,(p->>'grossAmount')::numeric) OR (NEW.content->>'tenantId',NEW.content->>'bookId',NEW.content->>'yearId',NEW.content->>'legalEntityId',NEW.content->>'preparedBy',NEW.content->>'schemaVersion') IS DISTINCT FROM (NEW.tenant_id::text,NEW.book_id::text,NEW.year_id::text,NEW.legal_entity_id::text,NEW.prepared_by::text,'cash-allocation/1') THEN RAISE EXCEPTION 'CASH_ALLOCATION_SNAPSHOT_MISMATCH';END IF;
  IF (NEW.content->>'supersedesAllocationId',(NEW.content->>'expectedSupersededVersion')::bigint,NEW.content->>'supersededContentDigest',(NEW.content->>'normalizedTotal')::numeric) IS DISTINCT FROM (NEW.supersedes_allocation_id::text,NEW.expected_superseded_version,NEW.superseded_content_digest,NEW.total) OR coalesce(length(NEW.content->>'reason'),0) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'CASH_ALLOCATION_CONTENT_BINDING_MISMATCH';END IF;
  IF NEW.supersedes_allocation_id IS NULL THEN IF EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_effect WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND review_id=NEW.review_id) THEN RAISE EXCEPTION 'CASH_ALLOCATION_ALREADY_EFFECTIVE';END IF;
  ELSE
   SELECT * INTO STRICT old_alloc FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.supersedes_allocation_id;
   IF old_alloc.status<>'APPROVED' OR old_alloc.review_id<>NEW.review_id OR old_alloc.version<>NEW.expected_superseded_version OR old_alloc.content_digest<>NEW.superseded_content_digest OR NOT EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_effect WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND review_id=NEW.review_id AND allocation_id=old_alloc.id AND dependency_id=old_alloc.approved_dependency_id) THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_PARENT_STALE';END IF;
  END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','version','submitted_at','submission_expires_at','approved_by','approved_at','approved_dependency_id','activation_replacement_id','decision_by','decision_at','decision_reason','release_request_id','supersession_request_id','superseded_by_allocation_id','released_by','released_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','submitted_at','submission_expires_at','approved_by','approved_at','approved_dependency_id','activation_replacement_id','decision_by','decision_at','decision_reason','release_request_id','supersession_request_id','superseded_by_allocation_id','released_by','released_at']) OR NEW.version<>OLD.version+1 OR NOT ((OLD.status='DRAFT' AND NEW.status IN('SUBMITTED','REJECTED','CANCELLED')) OR (OLD.status='SUBMITTED' AND NEW.status IN('APPROVED','REJECTED','CANCELLED')) OR (OLD.status='APPROVED' AND NEW.status IN('RELEASED','SUPERSEDED'))) THEN RAISE EXCEPTION 'CASH_ALLOCATION_CONTENT_OR_TRANSITION_INVALID';END IF;
  IF OLD.submitted_at IS NOT NULL AND (NEW.submitted_at,NEW.submission_expires_at) IS DISTINCT FROM (OLD.submitted_at,OLD.submission_expires_at) THEN RAISE EXCEPTION 'CASH_ALLOCATION_SUBMISSION_IMMUTABLE';END IF;
  IF NEW.status='SUBMITTED' AND (NEW.submitted_at IS NULL OR NEW.submission_expires_at IS DISTINCT FROM NEW.submitted_at+interval '168 hours' OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL OR NEW.approved_dependency_id IS NOT NULL OR NEW.activation_replacement_id IS NOT NULL OR NEW.decision_by IS NOT NULL OR NEW.decision_at IS NOT NULL OR NEW.decision_reason IS NOT NULL OR NEW.release_request_id IS NOT NULL OR NEW.supersession_request_id IS NOT NULL OR NEW.superseded_by_allocation_id IS NOT NULL OR NEW.released_by IS NOT NULL OR NEW.released_at IS NOT NULL) THEN RAISE EXCEPTION 'CASH_ALLOCATION_SUBMISSION_METADATA';END IF;
  IF NEW.status IN('APPROVED','REJECTED','CANCELLED') AND (NEW.decision_by IS NULL OR NEW.decision_at IS NULL OR coalesce(length(NEW.decision_reason),0) NOT BETWEEN 1 AND 1000) THEN RAISE EXCEPTION 'CASH_ALLOCATION_DECISION_REQUIRED';END IF;
  IF NEW.status IN('APPROVED','REJECTED') AND NEW.decision_by IN(raw.prepared_by,NEW.prepared_by,NEW.last_edited_by) THEN RAISE EXCEPTION 'CASH_ALLOCATION_INDEPENDENT_APPROVER_REQUIRED';END IF;
  IF NEW.status='CANCELLED' AND NEW.decision_by<>NEW.prepared_by THEN RAISE EXCEPTION 'CASH_ALLOCATION_ORIGINAL_MAKER_REQUIRED';END IF;
  IF NEW.status IN('REJECTED','CANCELLED') AND EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_replacement WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND new_allocation_id=NEW.id AND status='REQUESTED') THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_PENDING';END IF;
  IF NEW.status IN('REJECTED','CANCELLED') AND (NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL OR NEW.approved_dependency_id IS NOT NULL OR NEW.activation_replacement_id IS NOT NULL OR NEW.release_request_id IS NOT NULL OR NEW.supersession_request_id IS NOT NULL OR NEW.superseded_by_allocation_id IS NOT NULL OR NEW.released_by IS NOT NULL OR NEW.released_at IS NOT NULL) THEN RAISE EXCEPTION 'CASH_ALLOCATION_TERMINAL_METADATA';END IF;
  IF NEW.status IN('SUBMITTED','APPROVED') THEN p:=plugin_finance_cash_allocation_parent(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.review_id);IF p IS DISTINCT FROM NEW.content->'parentSnapshot' THEN RAISE EXCEPTION 'CASH_ALLOCATION_PARENT_STALE';END IF;PERFORM plugin_finance_cash_allocation_fresh_lines(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.id);END IF;
  IF NEW.status='APPROVED' THEN
   IF NEW.approved_dependency_id IS NULL OR NEW.approved_by IS DISTINCT FROM NEW.decision_by OR NEW.approved_at IS DISTINCT FROM NEW.decision_at OR NEW.submission_expires_at IS NULL OR NEW.submission_expires_at<=clock_timestamp() OR NEW.release_request_id IS NOT NULL OR NEW.supersession_request_id IS NOT NULL OR NEW.superseded_by_allocation_id IS NOT NULL OR NEW.released_by IS NOT NULL OR NEW.released_at IS NOT NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_APPROVAL_EXPIRED_OR_INVALID';END IF;
   IF NEW.supersedes_allocation_id IS NOT NULL THEN
    SELECT * INTO decision FROM plugin_finance_cash_allocation_replacement WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.activation_replacement_id AND status='APPROVED' AND new_allocation_id=NEW.id AND new_content_digest=NEW.content_digest AND new_dependency_id=NEW.approved_dependency_id AND old_allocation_id=NEW.supersedes_allocation_id;
    IF NOT FOUND OR decision.reviewed_by<>NEW.approved_by OR decision.reviewed_at<>NEW.approved_at THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_REQUIRED';END IF;
   ELSIF NEW.activation_replacement_id IS NOT NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_UNEXPECTED_REPLACEMENT';END IF;
  END IF;
  IF NEW.status IN('RELEASED','SUPERSEDED') THEN
   IF (NEW.approved_by,NEW.approved_at,NEW.approved_dependency_id,NEW.activation_replacement_id,NEW.decision_by,NEW.decision_at,NEW.decision_reason) IS DISTINCT FROM (OLD.approved_by,OLD.approved_at,OLD.approved_dependency_id,OLD.activation_replacement_id,OLD.decision_by,OLD.decision_at,OLD.decision_reason) OR NEW.released_by IS NULL OR NEW.released_at IS NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_ACTIVATION_HISTORY_IMMUTABLE';END IF;
   IF NEW.status='RELEASED' THEN
    PERFORM 1 FROM plugin_finance_cash_allocation_release WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.release_request_id AND allocation_id=NEW.id AND dependency_id=NEW.approved_dependency_id AND status='APPROVED' AND reviewed_by=NEW.released_by AND reviewed_at=NEW.released_at;
    IF NOT FOUND OR NEW.supersession_request_id IS NOT NULL OR NEW.superseded_by_allocation_id IS NOT NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_TYPED_RELEASE_REQUIRED';END IF;
   ELSE
    PERFORM 1 FROM plugin_finance_cash_allocation_replacement WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.supersession_request_id AND old_allocation_id=NEW.id AND old_dependency_id=NEW.approved_dependency_id AND new_allocation_id=NEW.superseded_by_allocation_id AND status='APPROVED' AND reviewed_by=NEW.released_by AND reviewed_at=NEW.released_at;
    IF NOT FOUND OR NEW.release_request_id IS NOT NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_TYPED_REPLACEMENT_REQUIRED';END IF;
   END IF;
  END IF;
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_cash_allocation FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_guard_fn();
CREATE FUNCTION plugin_finance_cash_allocation_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a record;e jsonb;o record;p record;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'CASH_ALLOCATION_LINE_IMMUTABLE';END IF;
 SELECT * INTO STRICT a FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.allocation_id;
 SELECT * INTO STRICT p FROM plugin_finance_cash_policy_revision WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.policy_id;
 SELECT * INTO STRICT o FROM plugin_finance_original WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.evidence_original_id;
 e:=a.content->'lines'->(NEW.line_no-1);
 IF a.status<>'DRAFT' OR e IS DISTINCT FROM jsonb_build_object('lineNo',NEW.line_no,'componentKey',NEW.component_key,'normalizedAmount',NEW.amount::text,'policySnapshot',NEW.policy_snapshot,'businessPurpose',NEW.business_purpose,'purposeEvidence',jsonb_build_object('originalId',NEW.evidence_original_id,'version',NEW.evidence_version,'sha256',NEW.evidence_sha256,'filename',NEW.evidence_filename),'description',NEW.description,'ordinaryPurposeConfirmed',NEW.ordinary_purpose_confirmed) OR (p.version,p.content_digest,p.business_purpose) IS DISTINCT FROM (NEW.policy_version,NEW.policy_content_digest,NEW.business_purpose) OR (o.version,o.sha256,o.filename) IS DISTINCT FROM (NEW.evidence_version,NEW.evidence_sha256,NEW.evidence_filename) OR encode(sha256(o.content),'hex')<>NEW.evidence_sha256 OR NEW.policy_snapshot IS DISTINCT FROM plugin_finance_cash_allocation_policy_snapshot(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.policy_id) THEN RAISE EXCEPTION 'CASH_ALLOCATION_LINE_SNAPSHOT_MISMATCH';END IF;RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_line_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_cash_allocation_line FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_line_guard();
CREATE FUNCTION plugin_finance_cash_allocation_dependency_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a record;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CASH_ALLOCATION_DEPENDENCY_HISTORY_IMMUTABLE';END IF;
 SELECT * INTO STRICT a FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.allocation_id;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ACTIVE' OR a.status<>'APPROVED' OR a.approved_dependency_id IS DISTINCT FROM NEW.id OR (NEW.activated_by,NEW.activated_at,NEW.activation_replacement_id) IS DISTINCT FROM (a.approved_by,a.approved_at,a.activation_replacement_id) OR NEW.release_request_id IS NOT NULL OR NEW.replacement_request_id IS NOT NULL OR NEW.released_by IS NOT NULL OR NEW.released_at IS NOT NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_APPROVED_CONSUMER_REQUIRED';END IF;
  PERFORM plugin_finance_cash_allocation_parent(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.review_id);
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','release_request_id','replacement_request_id','released_by','released_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','release_request_id','replacement_request_id','released_by','released_at']) OR OLD.state<>'ACTIVE' OR NEW.state<>'RELEASED' OR a.status NOT IN('RELEASED','SUPERSEDED') OR (NEW.release_request_id,NEW.replacement_request_id,NEW.released_by,NEW.released_at) IS DISTINCT FROM (a.release_request_id,a.supersession_request_id,a.released_by,a.released_at) OR (NEW.release_request_id IS NULL)=(NEW.replacement_request_id IS NULL) THEN RAISE EXCEPTION 'CASH_ALLOCATION_TYPED_RELEASE_REQUIRED';END IF;
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_dependency_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_cash_allocation_dependency FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_dependency_guard();
CREATE FUNCTION plugin_finance_cash_allocation_pointer_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a record;pv bigint;BEGIN
 IF TG_OP='DELETE' THEN
  SELECT * INTO STRICT a FROM plugin_finance_cash_allocation WHERE tenant_id=OLD.tenant_id AND book_id=OLD.book_id AND year_id=OLD.year_id AND id=OLD.allocation_id;
  IF a.status<>'RELEASED' OR a.approved_dependency_id<>OLD.dependency_id OR a.release_request_id IS NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_POINTER_RELEASE_REQUIRED';END IF;RETURN OLD;
 END IF;
 SELECT * INTO STRICT a FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.allocation_id;
 SELECT allocation_version INTO STRICT pv FROM plugin_finance_cash_allocation_guard WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id;
 IF a.status<>'APPROVED' OR a.approved_dependency_id<>NEW.dependency_id OR a.review_id<>NEW.review_id OR a.content_digest<>NEW.content_digest OR NEW.pointer_version<>pv THEN RAISE EXCEPTION 'CASH_ALLOCATION_POINTER_ACTIVATION_REQUIRED';END IF;
 IF TG_OP='INSERT' THEN IF a.supersedes_allocation_id IS NOT NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_POINTER_MISSING';END IF;
 ELSE
  IF (NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.review_id,NEW.review_usage_id,NEW.claim_id,NEW.raw_registration_id,NEW.claim_generation,NEW.claim_content_digest,NEW.review_content_digest) IS DISTINCT FROM (OLD.tenant_id,OLD.book_id,OLD.year_id,OLD.review_id,OLD.review_usage_id,OLD.claim_id,OLD.raw_registration_id,OLD.claim_generation,OLD.claim_content_digest,OLD.review_content_digest) OR NEW.pointer_version<=OLD.pointer_version OR a.supersedes_allocation_id IS DISTINCT FROM OLD.allocation_id THEN RAISE EXCEPTION 'CASH_ALLOCATION_POINTER_REPARENT_FORBIDDEN';END IF;
  PERFORM 1 FROM plugin_finance_cash_allocation_replacement WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=a.activation_replacement_id AND status='APPROVED' AND old_allocation_id=OLD.allocation_id AND old_dependency_id=OLD.dependency_id AND new_allocation_id=NEW.allocation_id AND new_dependency_id=NEW.dependency_id;IF NOT FOUND THEN RAISE EXCEPTION 'CASH_ALLOCATION_POINTER_TYPED_REPLACEMENT_REQUIRED';END IF;
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_pointer_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_cash_allocation_effect FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_pointer_guard();
CREATE FUNCTION plugin_finance_cash_allocation_release_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a record;raw record;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_HISTORY_IMMUTABLE';END IF;
 SELECT * INTO STRICT a FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.allocation_id;
 SELECT * INTO STRICT raw FROM plugin_finance_cash_movement_registration WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=a.raw_registration_id FOR UPDATE;
 PERFORM plugin_finance_cash_match_open(NEW.tenant_id,NEW.book_id,NEW.year_id,raw.occurred_date);
 IF a.status<>'APPROVED' OR a.version<>NEW.expected_allocation_version OR a.content_digest<>NEW.allocation_content_digest OR a.approved_dependency_id<>NEW.dependency_id THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_TARGET_STALE';END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'REQUESTED' OR NEW.version<>1 OR NEW.review_expires_at IS DISTINCT FROM NEW.requested_at+interval '168 hours' OR NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.decision_reason IS NOT NULL OR (NEW.content->>'allocationId',NEW.content->>'dependencyId',NEW.content->>'allocationContentDigest',NEW.content->>'requestedBy',NEW.content->>'reason') IS DISTINCT FROM (a.id::text,a.approved_dependency_id::text,a.content_digest,NEW.requested_by::text,NEW.reason) OR (NEW.content->>'expectedAllocationVersion')::bigint IS DISTINCT FROM a.version THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_INITIAL_SNAPSHOT';END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','version','reviewed_by','reviewed_at','decision_reason']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','reviewed_by','reviewed_at','decision_reason']) OR OLD.status<>'REQUESTED' OR NEW.status NOT IN('APPROVED','REJECTED','CANCELLED') OR NEW.version<>OLD.version+1 OR NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL OR coalesce(length(NEW.decision_reason),0) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_TRANSITION';END IF;
  IF NEW.status='CANCELLED' AND NEW.reviewed_by<>NEW.requested_by THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_REQUESTER_REQUIRED';END IF;
  IF NEW.status IN('APPROVED','REJECTED') AND NEW.reviewed_by IN(NEW.requested_by,raw.prepared_by,a.prepared_by,a.last_edited_by) THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_INDEPENDENCE';END IF;
  IF NEW.status='APPROVED' AND NEW.review_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_EXPIRED';END IF;
 END IF;
 IF NEW.status NOT IN('REJECTED','CANCELLED') AND EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_replacement WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND old_allocation_id=a.id AND status='REQUESTED') THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_PENDING';END IF;RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_release_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_cash_allocation_release FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_release_guard();
CREATE FUNCTION plugin_finance_cash_allocation_replacement_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE old_a record;new_a record;raw record;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_HISTORY_IMMUTABLE';END IF;
 SELECT * INTO STRICT old_a FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.old_allocation_id;
 SELECT * INTO STRICT new_a FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.new_allocation_id;
 SELECT * INTO STRICT raw FROM plugin_finance_cash_movement_registration WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=old_a.raw_registration_id FOR UPDATE;
 PERFORM plugin_finance_cash_match_open(NEW.tenant_id,NEW.book_id,NEW.year_id,raw.occurred_date);
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'REQUESTED' OR NEW.version<>1 OR NEW.new_dependency_id IS NOT NULL OR NEW.review_expires_at IS DISTINCT FROM NEW.requested_at+interval '168 hours' OR NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.decision_reason IS NOT NULL OR NEW.requested_by<>new_a.prepared_by THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_INITIAL';END IF;
  IF (NEW.content->>'oldAllocationId',NEW.content->>'oldDependencyId',NEW.content->>'oldContentDigest',NEW.content->>'newAllocationId',NEW.content->>'newContentDigest',NEW.content->>'parentReviewId',NEW.content->>'claimId',NEW.content->>'requestedBy',NEW.content->>'reason') IS DISTINCT FROM (old_a.id::text,old_a.approved_dependency_id::text,old_a.content_digest,new_a.id::text,new_a.content_digest,old_a.review_id::text,old_a.claim_id::text,NEW.requested_by::text,NEW.reason) OR (NEW.content->>'expectedOldVersion')::bigint IS DISTINCT FROM old_a.version OR (NEW.content->>'expectedNewVersion')::bigint IS DISTINCT FROM new_a.version THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_SNAPSHOT';END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','version','new_dependency_id','reviewed_by','reviewed_at','decision_reason']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','new_dependency_id','reviewed_by','reviewed_at','decision_reason']) OR OLD.status<>'REQUESTED' OR NEW.status NOT IN('APPROVED','REJECTED','CANCELLED') OR NEW.version<>OLD.version+1 OR NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL OR coalesce(length(NEW.decision_reason),0) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_TRANSITION';END IF;
  IF NEW.status='CANCELLED' AND NEW.reviewed_by<>NEW.requested_by THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_REQUESTER';END IF;
  IF NEW.status IN('APPROVED','REJECTED') AND NEW.reviewed_by IN(NEW.requested_by,raw.prepared_by,old_a.prepared_by,new_a.prepared_by,new_a.last_edited_by) THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_INDEPENDENCE';END IF;
  IF NEW.status='APPROVED' AND (NEW.review_expires_at<=clock_timestamp() OR new_a.submission_expires_at<=clock_timestamp() OR NEW.new_dependency_id IS NULL) THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_EXPIRED';END IF;
  IF NEW.status IN('REJECTED','CANCELLED') AND NEW.new_dependency_id IS NOT NULL THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_FALSE_EFFECT';END IF;
 END IF;
 IF NEW.status IN('REQUESTED','APPROVED') THEN
  IF old_a.status<>'APPROVED' OR old_a.version<>NEW.expected_old_version OR old_a.content_digest<>NEW.old_content_digest OR old_a.approved_dependency_id<>NEW.old_dependency_id OR new_a.status<>'SUBMITTED' OR new_a.version<>NEW.expected_new_version OR new_a.content_digest<>NEW.new_content_digest OR new_a.supersedes_allocation_id IS DISTINCT FROM old_a.id OR (new_a.expected_superseded_version,new_a.superseded_content_digest) IS DISTINCT FROM (old_a.version,old_a.content_digest) OR (old_a.review_id,old_a.review_usage_id,old_a.review_content_digest,old_a.claim_id,old_a.raw_registration_id,old_a.claim_generation,old_a.claim_content_digest,old_a.source_match_generation) IS DISTINCT FROM (new_a.review_id,new_a.review_usage_id,new_a.review_content_digest,new_a.claim_id,new_a.raw_registration_id,new_a.claim_generation,new_a.claim_content_digest,new_a.source_match_generation) OR NEW.review_id<>old_a.review_id OR NEW.claim_id<>old_a.claim_id THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_PAIR_STALE';END IF;
  IF NOT EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_effect WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND review_id=old_a.review_id AND allocation_id=old_a.id AND dependency_id=old_a.approved_dependency_id) OR EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_release WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND allocation_id=old_a.id AND status='REQUESTED') THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_PENDING_OR_EFFECT_STALE';END IF;
  PERFORM plugin_finance_cash_allocation_parent(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.review_id);
  IF NEW.status='APPROVED' THEN PERFORM plugin_finance_cash_allocation_fresh_lines(NEW.tenant_id,NEW.book_id,NEW.year_id,new_a.id);END IF;
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_replacement_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_cash_allocation_replacement FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_replacement_guard();
CREATE FUNCTION plugin_finance_cash_allocation_effects() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE pv bigint;BEGIN
 IF NEW.status='APPROVED' THEN
  IF NEW.activation_replacement_id IS NULL THEN UPDATE plugin_finance_cash_allocation_guard SET allocation_version=allocation_version+1 WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id;END IF;
  SELECT allocation_version INTO STRICT pv FROM plugin_finance_cash_allocation_guard WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id;
  INSERT INTO plugin_finance_cash_allocation_dependency(tenant_id,book_id,year_id,id,allocation_id,consumer_content_digest,review_id,review_usage_id,review_content_digest,claim_id,raw_registration_id,claim_generation,claim_content_digest,activated_by,activated_at,activation_replacement_id) VALUES(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.approved_dependency_id,NEW.id,NEW.content_digest,NEW.review_id,NEW.review_usage_id,NEW.review_content_digest,NEW.claim_id,NEW.raw_registration_id,NEW.claim_generation,NEW.claim_content_digest,NEW.approved_by,NEW.approved_at,NEW.activation_replacement_id);
  INSERT INTO plugin_finance_cash_allocation_activation VALUES(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.id,NEW.approved_dependency_id,NEW.content_digest,NEW.review_id,NEW.review_usage_id,NEW.claim_id,NEW.raw_registration_id,NEW.claim_generation,NEW.claim_content_digest,NEW.review_content_digest,NEW.approved_by,NEW.approved_at,NEW.activation_replacement_id);
  IF NEW.activation_replacement_id IS NULL THEN
   INSERT INTO plugin_finance_cash_allocation_effect VALUES(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.review_id,NEW.id,NEW.approved_dependency_id,NEW.content_digest,NEW.review_usage_id,NEW.claim_id,NEW.raw_registration_id,NEW.claim_generation,NEW.claim_content_digest,NEW.review_content_digest,pv);
  ELSE
   UPDATE plugin_finance_cash_allocation_effect SET allocation_id=NEW.id,dependency_id=NEW.approved_dependency_id,content_digest=NEW.content_digest,pointer_version=pv WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND review_id=NEW.review_id AND allocation_id=NEW.supersedes_allocation_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_POINTER_MISSING';END IF;
  END IF;
 ELSIF NEW.status IN('RELEASED','SUPERSEDED') THEN
  IF NEW.status='RELEASED' THEN UPDATE plugin_finance_cash_allocation_guard SET allocation_version=allocation_version+1 WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id;END IF;
  UPDATE plugin_finance_cash_allocation_dependency SET state='RELEASED',release_request_id=NEW.release_request_id,replacement_request_id=NEW.supersession_request_id,released_by=NEW.released_by,released_at=NEW.released_at WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.approved_dependency_id AND state='ACTIVE';IF NOT FOUND THEN RAISE EXCEPTION 'CASH_ALLOCATION_ACTIVE_DEPENDENCY_REQUIRED';END IF;
  IF NEW.status='RELEASED' THEN DELETE FROM plugin_finance_cash_allocation_effect WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND review_id=NEW.review_id AND allocation_id=NEW.id;IF NOT FOUND THEN RAISE EXCEPTION 'CASH_ALLOCATION_ACTIVE_POINTER_REQUIRED';END IF;END IF;
 END IF;
 SELECT allocation_version INTO STRICT pv FROM plugin_finance_cash_allocation_guard WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id;
 INSERT INTO plugin_finance_cash_allocation_outbox VALUES(NEW.tenant_id,NEW.book_id,NEW.year_id,gen_random_uuid(),NEW.id,NULL,'ALLOCATION',NEW.version,pv,'ALLOCATION_'||NEW.status,to_jsonb(NEW),now());RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_effects AFTER INSERT OR UPDATE OF status ON plugin_finance_cash_allocation FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_effects();
CREATE FUNCTION plugin_finance_cash_allocation_release_effects() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE pv bigint;BEGIN
 IF NEW.status IN('REQUESTED','REJECTED','CANCELLED') THEN UPDATE plugin_finance_cash_allocation_guard SET allocation_version=allocation_version+1 WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id;
 ELSIF NEW.status='APPROVED' THEN UPDATE plugin_finance_cash_allocation SET status='RELEASED',version=version+1,release_request_id=NEW.id,released_by=NEW.reviewed_by,released_at=NEW.reviewed_at WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.allocation_id AND status='APPROVED' AND approved_dependency_id=NEW.dependency_id;IF NOT FOUND THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_TARGET_STALE';END IF;END IF;
 SELECT allocation_version INTO STRICT pv FROM plugin_finance_cash_allocation_guard WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id;
 INSERT INTO plugin_finance_cash_allocation_outbox VALUES(NEW.tenant_id,NEW.book_id,NEW.year_id,gen_random_uuid(),NEW.allocation_id,NEW.id,'RELEASE',NEW.version,pv,'RELEASE_'||NEW.status,to_jsonb(NEW),now());RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_release_effects AFTER INSERT OR UPDATE OF status ON plugin_finance_cash_allocation_release FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_release_effects();
CREATE FUNCTION plugin_finance_cash_allocation_replacement_effects() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE pv bigint;BEGIN
 UPDATE plugin_finance_cash_allocation_guard SET allocation_version=allocation_version+1 WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id RETURNING allocation_version INTO pv;
 IF NEW.status='APPROVED' THEN
  UPDATE plugin_finance_cash_allocation SET status='SUPERSEDED',version=version+1,supersession_request_id=NEW.id,superseded_by_allocation_id=NEW.new_allocation_id,released_by=NEW.reviewed_by,released_at=NEW.reviewed_at WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.old_allocation_id AND status='APPROVED' AND approved_dependency_id=NEW.old_dependency_id;IF NOT FOUND THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_OLD_STALE';END IF;
  UPDATE plugin_finance_cash_allocation SET status='APPROVED',version=version+1,approved_by=NEW.reviewed_by,approved_at=NEW.reviewed_at,approved_dependency_id=NEW.new_dependency_id,activation_replacement_id=NEW.id,decision_by=NEW.reviewed_by,decision_at=NEW.reviewed_at,decision_reason=NEW.decision_reason WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.new_allocation_id AND status='SUBMITTED' AND version=NEW.expected_new_version;IF NOT FOUND THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_NEW_STALE';END IF;
 END IF;
 INSERT INTO plugin_finance_cash_allocation_outbox VALUES(NEW.tenant_id,NEW.book_id,NEW.year_id,gen_random_uuid(),NEW.new_allocation_id,NEW.id,'REPLACEMENT',NEW.version,pv,'REPLACEMENT_'||NEW.status,to_jsonb(NEW),now());RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_replacement_effects AFTER INSERT OR UPDATE OF status ON plugin_finance_cash_allocation_replacement FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_replacement_effects();
CREATE FUNCTION plugin_finance_cash_allocation_replacement_committed(t uuid,b uuid,y uuid,rid uuid) RETURNS void LANGUAGE plpgsql AS $$ DECLARE r record;old_a record;new_a record;d record;receipt record;BEGIN
 SELECT * INTO STRICT r FROM plugin_finance_cash_allocation_replacement WHERE tenant_id=t AND book_id=b AND year_id=y AND id=rid;
 IF r.status<>'APPROVED' THEN RETURN;END IF;
 SELECT * INTO STRICT old_a FROM plugin_finance_cash_allocation WHERE tenant_id=t AND book_id=b AND year_id=y AND id=r.old_allocation_id;
 SELECT * INTO STRICT new_a FROM plugin_finance_cash_allocation WHERE tenant_id=t AND book_id=b AND year_id=y AND id=r.new_allocation_id;
 SELECT * INTO STRICT d FROM plugin_finance_cash_allocation_dependency WHERE tenant_id=t AND book_id=b AND year_id=y AND id=r.old_dependency_id;
 SELECT * INTO receipt FROM plugin_finance_cash_allocation_activation WHERE tenant_id=t AND book_id=b AND year_id=y AND allocation_id=r.new_allocation_id;
 IF NOT FOUND OR old_a.status<>'SUPERSEDED' OR old_a.supersession_request_id IS DISTINCT FROM r.id OR old_a.superseded_by_allocation_id IS DISTINCT FROM r.new_allocation_id OR d.state<>'RELEASED' OR d.replacement_request_id IS DISTINCT FROM r.id OR new_a.status NOT IN('APPROVED','RELEASED','SUPERSEDED') OR new_a.activation_replacement_id IS DISTINCT FROM r.id OR new_a.approved_dependency_id IS DISTINCT FROM r.new_dependency_id OR (receipt.replacement_id,receipt.dependency_id,receipt.content_digest,receipt.approved_by,receipt.approved_at) IS DISTINCT FROM (r.id,r.new_dependency_id,r.new_content_digest,r.reviewed_by,r.reviewed_at) OR old_a.review_id<>new_a.review_id THEN RAISE EXCEPTION 'CASH_ALLOCATION_REPLACEMENT_COMMITTED_HISTORY_REQUIRED';END IF;
END $$;
CREATE FUNCTION plugin_finance_cash_allocation_committed(t uuid,b uuid,y uuid,aid uuid) RETURNS void LANGUAGE plpgsql AS $$
DECLARE a record;d record;receipt record;r record;u record;c record;g bigint;n integer;effects integer;lines integer;sum_amount numeric;
BEGIN
 SELECT * INTO STRICT a FROM plugin_finance_cash_allocation WHERE tenant_id=t AND book_id=b AND year_id=y AND id=aid;
 SELECT count(*) INTO n FROM plugin_finance_cash_allocation_dependency WHERE tenant_id=t AND book_id=b AND year_id=y AND allocation_id=aid;
 SELECT count(*) INTO effects FROM plugin_finance_cash_allocation_effect WHERE tenant_id=t AND book_id=b AND year_id=y AND allocation_id=aid;
 IF a.status IN('DRAFT','SUBMITTED','REJECTED','CANCELLED') THEN IF n<>0 OR effects<>0 OR a.approved_dependency_id IS NOT NULL OR EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_activation WHERE tenant_id=t AND book_id=b AND year_id=y AND allocation_id=aid) THEN RAISE EXCEPTION 'CASH_ALLOCATION_NON_EFFECTIVE_HAS_DEPENDENCY';END IF;RETURN;END IF;
 SELECT * INTO d FROM plugin_finance_cash_allocation_dependency WHERE tenant_id=t AND book_id=b AND year_id=y AND id=a.approved_dependency_id AND allocation_id=aid;
 IF NOT FOUND OR n<>1 OR (d.consumer_content_digest,d.review_id,d.review_usage_id,d.claim_id,d.raw_registration_id,d.claim_generation,d.claim_content_digest,d.review_content_digest,d.activated_by,d.activated_at,d.activation_replacement_id) IS DISTINCT FROM (a.content_digest,a.review_id,a.review_usage_id,a.claim_id,a.raw_registration_id,a.claim_generation,a.claim_content_digest,a.review_content_digest,a.approved_by,a.approved_at,a.activation_replacement_id) THEN RAISE EXCEPTION 'CASH_ALLOCATION_EXACT_TYPED_DEPENDENCY_REQUIRED';END IF;
 SELECT * INTO receipt FROM plugin_finance_cash_allocation_activation WHERE tenant_id=t AND book_id=b AND year_id=y AND allocation_id=aid;
 IF NOT FOUND OR (receipt.dependency_id,receipt.content_digest,receipt.approved_by,receipt.approved_at,receipt.replacement_id) IS DISTINCT FROM (a.approved_dependency_id,a.content_digest,a.approved_by,a.approved_at,a.activation_replacement_id) THEN RAISE EXCEPTION 'CASH_ALLOCATION_ACTIVATION_RECEIPT_REQUIRED';END IF;
 SELECT count(*),sum(amount) INTO lines,sum_amount FROM plugin_finance_cash_allocation_line WHERE tenant_id=t AND book_id=b AND year_id=y AND allocation_id=aid;
 SELECT * INTO STRICT r FROM plugin_finance_cash_source_review WHERE tenant_id=t AND book_id=b AND year_id=y AND id=a.review_id;
 IF lines<1 OR lines>20 OR lines<>jsonb_array_length(a.content->'lines') OR sum_amount IS DISTINCT FROM a.total OR a.total IS DISTINCT FROM (r.content->'claimSnapshot'->>'normalizedAmount')::numeric THEN RAISE EXCEPTION 'CASH_ALLOCATION_COMMITTED_GROSS_MISMATCH';END IF;
 IF a.status='APPROVED' THEN
  SELECT * INTO STRICT u FROM plugin_finance_cash_claim_usage WHERE tenant_id=t AND book_id=b AND year_id=y AND id=a.review_usage_id;
  SELECT * INTO STRICT c FROM plugin_finance_cash_leg_claim WHERE tenant_id=t AND book_id=b AND year_id=y AND id=a.claim_id;
  SELECT source_generation INTO STRICT g FROM plugin_finance_cash_source_match_guard WHERE tenant_id=t AND book_id=b AND year_id=y AND raw_registration_id=a.raw_registration_id;
  IF d.state<>'ACTIVE' OR effects<>1 OR r.status<>'APPROVED' OR u.state<>'ACTIVE' OR c.state<>'ACTIVE' OR g<>a.source_match_generation OR EXISTS(SELECT 1 FROM plugin_finance_cash_source_review_release WHERE tenant_id=t AND book_id=b AND year_id=y AND review_id=a.review_id AND status='REQUESTED') OR NOT EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_effect WHERE tenant_id=t AND book_id=b AND year_id=y AND review_id=a.review_id AND allocation_id=aid AND dependency_id=d.id AND content_digest=a.content_digest) THEN RAISE EXCEPTION 'CASH_ALLOCATION_ACTIVE_PARENT_POINTER_INVARIANT';END IF;
 ELSE
  IF d.state<>'RELEASED' OR effects<>0 OR (d.release_request_id,d.replacement_request_id,d.released_by,d.released_at) IS DISTINCT FROM (a.release_request_id,a.supersession_request_id,a.released_by,a.released_at) OR (d.release_request_id IS NULL)=(d.replacement_request_id IS NULL) THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASED_DEPENDENCY_INVARIANT';END IF;
  IF a.status='RELEASED' THEN PERFORM 1 FROM plugin_finance_cash_allocation_release WHERE tenant_id=t AND book_id=b AND year_id=y AND id=a.release_request_id AND allocation_id=aid AND dependency_id=d.id AND status='APPROVED' AND reviewed_by=a.released_by AND reviewed_at=a.released_at;IF NOT FOUND THEN RAISE EXCEPTION 'CASH_ALLOCATION_APPROVED_RELEASE_REQUIRED';END IF;
  ELSE PERFORM plugin_finance_cash_allocation_replacement_committed(t,b,y,a.supersession_request_id);END IF;
 END IF;
 IF a.activation_replacement_id IS NOT NULL THEN PERFORM plugin_finance_cash_allocation_replacement_committed(t,b,y,a.activation_replacement_id);END IF;
END $$;
CREATE FUNCTION plugin_finance_cash_allocation_final() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='plugin_finance_cash_allocation' THEN PERFORM plugin_finance_cash_allocation_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.id);
 ELSE PERFORM plugin_finance_cash_allocation_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.allocation_id);END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER finance_cash_allocation_final AFTER INSERT OR UPDATE ON plugin_finance_cash_allocation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_final();
CREATE CONSTRAINT TRIGGER finance_cash_allocation_dependency_final AFTER INSERT OR UPDATE ON plugin_finance_cash_allocation_dependency DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_final();
CREATE CONSTRAINT TRIGGER finance_cash_allocation_receipt_final AFTER INSERT ON plugin_finance_cash_allocation_activation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_final();
CREATE FUNCTION plugin_finance_cash_allocation_pointer_final() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN PERFORM plugin_finance_cash_allocation_committed(OLD.tenant_id,OLD.book_id,OLD.year_id,OLD.allocation_id);
 ELSE PERFORM plugin_finance_cash_allocation_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.allocation_id);IF TG_OP='UPDATE' AND NEW.allocation_id<>OLD.allocation_id THEN PERFORM plugin_finance_cash_allocation_committed(OLD.tenant_id,OLD.book_id,OLD.year_id,OLD.allocation_id);END IF;END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER finance_cash_allocation_pointer_final AFTER INSERT OR UPDATE OR DELETE ON plugin_finance_cash_allocation_effect DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_pointer_final();
CREATE FUNCTION plugin_finance_cash_allocation_decision_final() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='plugin_finance_cash_allocation_release' THEN IF NEW.status='APPROVED' THEN PERFORM plugin_finance_cash_allocation_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.allocation_id);IF NOT EXISTS(SELECT 1 FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.allocation_id AND status='RELEASED' AND release_request_id=NEW.id) THEN RAISE EXCEPTION 'CASH_ALLOCATION_RELEASE_DECISION_UNAPPLIED';END IF;END IF;
 ELSE IF NEW.status='APPROVED' THEN PERFORM plugin_finance_cash_allocation_replacement_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.id);PERFORM plugin_finance_cash_allocation_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.old_allocation_id);PERFORM plugin_finance_cash_allocation_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.new_allocation_id);END IF;END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER finance_cash_allocation_release_final AFTER INSERT OR UPDATE ON plugin_finance_cash_allocation_release DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_decision_final();
CREATE CONSTRAINT TRIGGER finance_cash_allocation_replacement_final AFTER INSERT OR UPDATE ON plugin_finance_cash_allocation_replacement DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_decision_final();
CREATE FUNCTION plugin_finance_cash_allocation_parent_unused(t uuid,b uuid,y uuid,rid uuid) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_dependency WHERE tenant_id=t AND book_id=b AND year_id=y AND review_id=rid AND state='ACTIVE') OR EXISTS(SELECT 1 FROM plugin_finance_cash_allocation_replacement WHERE tenant_id=t AND book_id=b AND year_id=y AND review_id=rid AND status='REQUESTED') THEN RAISE EXCEPTION 'CASH_REVIEW_IN_USE';END IF;
END $$;
CREATE FUNCTION plugin_finance_cash_allocation_parent_release_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='plugin_finance_cash_source_review_release' THEN IF NEW.status IN('REQUESTED','APPROVED') THEN PERFORM plugin_finance_cash_allocation_parent_unused(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.review_id);END IF;
 ELSIF TG_TABLE_NAME='plugin_finance_cash_source_review' THEN IF NEW.status='RELEASED' THEN PERFORM plugin_finance_cash_allocation_parent_unused(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.id);END IF;
 ELSE IF NEW.state='RELEASED' THEN PERFORM plugin_finance_cash_allocation_parent_unused(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.source_review_id);END IF;END IF;RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_allocation_parent_request_guard BEFORE INSERT OR UPDATE OF status ON plugin_finance_cash_source_review_release FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_parent_release_guard();
CREATE TRIGGER finance_cash_allocation_parent_review_guard BEFORE UPDATE OF status ON plugin_finance_cash_source_review FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_parent_release_guard();
CREATE TRIGGER finance_cash_allocation_parent_usage_guard BEFORE UPDATE OF state ON plugin_finance_cash_claim_usage FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_parent_release_guard();
CREATE FUNCTION plugin_finance_cash_allocation_parent_final() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE rid uuid;a record;BEGIN
 IF TG_TABLE_NAME='plugin_finance_cash_source_review' THEN rid:=NEW.id;ELSE rid:=NEW.source_review_id;END IF;
 FOR a IN SELECT id FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND review_id=rid AND status='APPROVED' LOOP PERFORM plugin_finance_cash_allocation_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,a.id);END LOOP;
 IF TG_TABLE_NAME='plugin_finance_cash_source_review' THEN IF NEW.status='RELEASED' THEN PERFORM plugin_finance_cash_allocation_parent_unused(NEW.tenant_id,NEW.book_id,NEW.year_id,rid);END IF;ELSE IF NEW.state='RELEASED' THEN PERFORM plugin_finance_cash_allocation_parent_unused(NEW.tenant_id,NEW.book_id,NEW.year_id,rid);END IF;END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER finance_cash_allocation_parent_review_final AFTER UPDATE ON plugin_finance_cash_source_review DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_parent_final();
CREATE CONSTRAINT TRIGGER finance_cash_allocation_parent_usage_final AFTER UPDATE ON plugin_finance_cash_claim_usage DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_parent_final();

CREATE FUNCTION plugin_finance_cash_allocation_parent_request_final() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a record;BEGIN
 IF NEW.status IN('REQUESTED','APPROVED') THEN
  FOR a IN SELECT id FROM plugin_finance_cash_allocation WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND review_id=NEW.review_id AND status='APPROVED' LOOP PERFORM plugin_finance_cash_allocation_committed(NEW.tenant_id,NEW.book_id,NEW.year_id,a.id);END LOOP;
  IF NEW.status='APPROVED' THEN PERFORM plugin_finance_cash_allocation_parent_unused(NEW.tenant_id,NEW.book_id,NEW.year_id,NEW.review_id);END IF;
 END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER finance_cash_allocation_parent_request_final AFTER INSERT OR UPDATE ON plugin_finance_cash_source_review_release DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_allocation_parent_request_final();
